try {
  const response = $input.item.json;
  if (!response) return [];
  // HTTP Request returns XML as string in 'data' or as the response itself
  const xml = typeof response === 'string' ? response : (response.data || response.body || '');
  if (!xml || typeof xml !== 'string') return [];
  // Extract <item> blocks from RSS XML
  const itemRegex = /<item[\s\S]*?<\/item>/gi;
  const matches = xml.match(itemRegex);
  if (!matches || matches.length === 0) return [];
  const getTag = (block, tag) => {
    const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\/' + tag + '>', 'i'));
    return m ? m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim() : '';
  };
  return matches.map(block => {
    const title = getTag(block, 'title');
    const link = getTag(block, 'link');
    const description = getTag(block, 'description');
    const pubDate = getTag(block, 'pubDate');
    const guid = getTag(block, 'guid') || link;
    return {
      json: {
        platform: 'exploit-db',
        external_id: String(guid || 'unknown'),
        text_content: description || title || '',
        language: 'en',
        created_at: pubDate ? new Date(pubDate).toISOString() : new Date().toISOString(),
        author_username: 'exploit-db',
        author_id: 'exploit-db',
        author_verified: true,
        author_followers_count: 0,
        author_description: null,
        likes_count: 0, shares_count: 0, replies_count: 0, views_count: 0,
        urls: link ? [link] : [],
        hashtags: [], mentions: [],
        has_media: false, is_reply: false, is_quote: false,
        reply_to_id: null, conversation_id: null,
        raw_data: { title: title, link: link, description: description, pubDate: pubDate, guid: guid }
      }
    };
  });
} catch (error) {
  console.error('Parse RSS ERROR:', error.message);
  return [];
}

