// Dedup intra-ejecución: elimina duplicados por (platform, external_id)
// dentro del mismo batch. La dedup inter-ejecución la maneja
// ON CONFLICT (platform, external_id) en el INSERT.
const items = $input.all();
if (!items || items.length === 0) return [];

const allowedPlatforms = new Set([
  'twitter',
  'reddit',
  'telegram',
  'discord',
  'github',
  'exploit-db',
  'hackernews',
  'other'
]);

const seen = new Set();
const unique = [];

for (const item of items) {
  const rawPlatform = String(item.json?.platform || 'other').trim().toLowerCase();
  const platform = allowedPlatforms.has(rawPlatform) ? rawPlatform : 'other';
  const id = String(item.json?.external_id || '').trim();
  const key = id ? platform + '::' + id : null;

  if (!key || !seen.has(key)) {
    if (key) {
      seen.add(key);
      item.json.platform = platform;
      item.json.external_id = id;
    }
    unique.push(item);
  }
}

return unique;

// =============================================
// Prep Existing Check
// Builds a compact, safe lookup query for existing
// social_mentions by the canonical identity:
//   (platform, external_id)
//
// Keep this output intentionally small. Do NOT carry
// full upstream items here; Filter Already Processed
// reads them directly from Deduplicate.
// =============================================

const items = $input.all();

const allowedPlatforms = new Set([
  'twitter',
  'reddit',
  'telegram',
  'discord',
  'github',
  'exploit-db',
  'hackernews',
  'other'
]);

const sqlString = (value) => {
  return String(value ?? '')
    .replace(/\0/g, '')
    .replace(/'/g, "''");
};

const keys = [];
const seen = new Set();

for (const item of items) {
  const rawPlatform = String(item.json?.platform || 'other').trim().toLowerCase();
  const platform = allowedPlatforms.has(rawPlatform) ? rawPlatform : 'other';
  const externalId = String(item.json?.external_id || '').trim();

  if (!externalId) continue;

  const key = platform + '::' + externalId;
  if (seen.has(key)) continue;

  seen.add(key);
  keys.push({ platform, external_id: externalId });
}

if (keys.length === 0) {
  return [{
    json: {
      lookup_count: 0,
      sample_keys: [],
      query: 'SELECT NULL::text AS platform, NULL::text AS external_id WHERE false;'
    }
  }];
}

const values = keys
  .map(k => "('" + sqlString(k.platform) + "', '" + sqlString(k.external_id) + "')")
  .join(',\n    ');

const query = [
  'WITH incoming(platform, external_id) AS (',
  '  VALUES',
  '    ' + values,
  ')',
  'SELECT sm.platform, sm.external_id',
  'FROM social_mentions sm',
  'JOIN incoming i',
  '  ON sm.platform = i.platform',
  ' AND sm.external_id = i.external_id;'
].join('\n');

return [{
  json: {
    lookup_count: keys.length,
    sample_keys: keys.slice(0, 10).map(k => k.platform + '::' + k.external_id),
    query
  }
}];

// =============================================
// Filter Already Processed
// Removes items whose (platform, external_id)
// already exist in social_mentions.
// This avoids calling Sentiment API + Threat
// Classification for items we already have.
// =============================================

const existingResults = $input.all();
const deduplicatedItems = $('Deduplicate').all();

// Build Set of existing keys from DB query result
const existingKeys = new Set();
for (const row of existingResults) {
  if (row.json.platform && row.json.external_id) {
    existingKeys.add(row.json.platform + '::' + row.json.external_id);
  }
}

// Filter out already-existing items
const newItems = [];
let skipped = 0;
for (const item of deduplicatedItems) {
  const key = (item.json.platform || '') + '::' + (item.json.external_id || '');
  if (existingKeys.has(key)) {
    skipped++;
  } else {
    newItems.push(item);
  }
}

if (skipped > 0) {
  console.log('Filter Already Processed: skipped ' + skipped + ' existing items, ' + newItems.length + ' new items to process');
}

return newItems.length > 0 ? newItems : [];

// =============================================
// Classify Threat
// Merges original data from Filter Already Processed with
// sentiment API response, then classifies threat.
// Index correlation is 1:1: Filter Already Processed → Sentiment → here.
// =============================================

const items = $input.all();
const deduplicateItems = $('Filter Already Processed').all();
// Safety check: items flow 1:1 from Filter Already Processed
// through Sentiment Analysis, so index correlation is safe.
if (items.length !== deduplicateItems.length) {
  console.warn('Classify Threat: item count mismatch — input=' + items.length + ' vs filtered=' + deduplicateItems.length);
}
const analyzedItems = [];

for (let i = 0; i < items.length; i++) {
  const sentimentResponse = items[i].json;
  const originalData = deduplicateItems[i]?.json || {};

  // Re-merge original data (HTTP Request replaces $json)
  const tweet = { ...originalData };

  // Detect Sentiment API error (continueOnFail returns {error:...})
  const sentimentFailed = !!(sentimentResponse.error || sentimentResponse.errorMessage);
  if (sentimentFailed) {
    console.warn('Classify Threat: Sentiment API failed for item ' + i + ' (external_id=' + (originalData.external_id || 'unknown') + '): ' + (sentimentResponse.errorMessage || sentimentResponse.error));
  }

  // Build sentiment object — use neutral defaults if API failed
  const sentiment = sentimentFailed ? {
    vader: {},
    textblob: {},
    ensemble_score: 0,
    sentiment_label: 'neutral',
    confidence_score: 0,
    api_error: true
  } : {
    vader: sentimentResponse.vader || {},
    textblob: sentimentResponse.textblob || {},
    ensemble_score: sentimentResponse.ensemble_score || 0,
    sentiment_label: sentimentResponse.sentiment_label || 'neutral',
    confidence_score: sentimentResponse.confidence_score || 0.5
  };

  // Classify threat based on content + sentiment
  const threatClassification = classifyThreat(tweet, sentiment);

  tweet.sentiment = sentiment;
  tweet.threat = threatClassification;
  analyzedItems.push({ json: tweet });
}

function getThreatCategory(threatType) {
  const categoryMap = {
    'ransomware': 'malware',
    'malware': 'malware',
    'data_breach': 'data_breach',
    'data breach': 'data_breach',
    'phishing': 'phishing',
    'potential_phishing': 'phishing',
    'exploit': 'vulnerability',
    'zero-day': 'vulnerability',
    'apt': 'advanced_threat',
    'ddos': 'ddos',
    'supply_chain': 'supply_chain',
    'vulnerability': 'vulnerability',
    'critical_security_incident': 'critical_incident',
    'security_threat': 'security_threat',
    'general': 'other'
  };
  return categoryMap[threatType] || 'other';
}

function classifyThreat(tweet, sentiment) {
  let score = 0;
  let matchedKeywords = [];
  let threatType = 'general';
  const rawText = tweet.text_content || '';
  const text = rawText.toLowerCase();

  // Critical keywords (highest weight)
  const criticalKeywords = {
    'ransomware': 30,
    'data breach': 30,
    'data leak': 30,
    'filtracion masiva': 30,
    'zero-day': 30,
    '0day': 30,
    'apt': 25,
    'supply chain attack': 30,
    'rce': 25,
    'remote code execution': 30
  };

  // High keywords
  const highKeywords = {
    'phishing': 20,
    'malware': 20,
    'exploit': 20,
    'vulnerabilidad critica': 20,
    'critical vulnerability': 20,
    'cve-': 20,
    'privilege escalation': 20,
    'compromised': 20,
    'comprometido': 20,
    'hacked': 20,
    'hackeado': 20,
    'backdoor': 20,
    'trojan': 20,
    'sql injection': 20,
    'xss': 15
  };

  // Medium keywords
  const mediumKeywords = {
    'attack': 10,
    'ataque': 10,
    'threat': 10,
    'amenaza': 10,
    'cyberattack': 15,
    'ciberataque': 15,
    'security': 5,
    'seguridad': 5,
    'incident': 10,
    'incidente': 10,
    'vulnerability': 10,
    'brute force': 10,
    'denial of service': 10,
    'ddos': 15
  };

  Object.entries(criticalKeywords).forEach(([kw, points]) => {
    if (text.includes(kw)) {
      score += points;
      matchedKeywords.push(kw);
      threatType = 'critical_security_incident';
    }
  });

  Object.entries(highKeywords).forEach(([kw, points]) => {
    if (text.includes(kw)) {
      score += points;
      matchedKeywords.push(kw);
      if (threatType === 'general') threatType = 'security_threat';
    }
  });

  Object.entries(mediumKeywords).forEach(([kw, points]) => {
    if (text.includes(kw)) {
      score += points;
      matchedKeywords.push(kw);
    }
  });

  // Sentiment boost
  if (sentiment.sentiment_label === 'negative') score += 15;

  // Engagement boost
  const totalEngagement = (tweet.likes_count || 0) +
    (tweet.shares_count || 0) +
    ((tweet.replies_count || 0) * 2);
  if (totalEngagement > 1000) score += 20;
  else if (totalEngagement > 100) score += 10;
  else if (totalEngagement > 10) score += 5;

  // Author credibility boost
  if (tweet.author_verified) score += 10;
  const followers = tweet.author_followers_count || 0;
  if (followers > 100000) score += 15;
  else if (followers > 10000) score += 10;
  else if (followers > 1000) score += 5;

  // URL analysis
  if (tweet.urls && tweet.urls.length > 0) {
    score += 5;
    const suspiciousTLDs = ['.tk', '.ml', '.ga', '.cf', '.gq', '.xyz', '.top'];
    if (tweet.urls.some(url => suspiciousTLDs.some(tld => url.toLowerCase().includes(tld)))) {
      score += 15;
      threatType = 'potential_phishing';
    }
  }

  // Determine criticality level
  let criticalityLevel;
  if (score >= 60) criticalityLevel = 'critical';
  else if (score >= 40) criticalityLevel = 'high';
  else if (score >= 20) criticalityLevel = 'medium';
  else criticalityLevel = 'low';

  return {
    threat_type: threatType,
    threat_category: getThreatCategory(threatType),
    criticality_level: criticalityLevel,
    confidence_score: Math.min(score / 100, 0.99),
    matched_keywords: matchedKeywords,
    raw_score: score
  };
}

return analyzedItems;

// =============================================
// Prep Mention Insert
// Builds deterministic SQL for social_mentions INSERT.
// Avoids Postgres queryReplacement for external OSINT text,
// arrays and JSON metadata by validating and escaping here.
// =============================================

const items = $input.all();
const result = [];

const validPlatforms = ['twitter', 'reddit', 'telegram', 'discord', 'github', 'exploit-db', 'hackernews', 'other'];

// SQL string escaping: remove null bytes and double single quotes.
// Values are inserted as single-quoted SQL literals below.
const cleanString = (val, fallback = '') => String(val ?? fallback).replace(/\0/g, '');
const sqlString = (val, fallback = '') => cleanString(val, fallback).replace(/'/g, "''");
const sqlText = (val, fallback = null, maxLen = null) => {
  if (val == null && fallback == null) return 'NULL';
  const raw = cleanString(val, fallback ?? '');
  const bounded = maxLen ? raw.slice(0, maxLen) : raw;
  return "'" + sqlString(bounded) + "'";
};
const sqlBool = (val) => val === true ? 'TRUE' : 'FALSE';
const sqlNonNegativeInt = (val) => {
  const n = Number(val);
  return Number.isFinite(n) && n > 0 ? String(Math.floor(n)) : '0';
};
const sqlTimestamp = (val) => {
  const date = new Date(val || Date.now());
  const safeDate = Number.isNaN(date.getTime()) ? new Date() : date;
  return "'" + safeDate.toISOString() + "'";
};
const sqlTextArray = (val, maxLen = null) => {
  if (!Array.isArray(val) || val.length === 0) return 'NULL';
  const values = val
    .filter(v => v != null)
    .map(v => {
      const clean = cleanString(v);
      return maxLen ? clean.slice(0, maxLen) : clean;
    })
    .filter(v => v.length > 0);
  return values.length > 0
    ? 'ARRAY[' + values.map(v => "'" + sqlString(v) + "'").join(', ') + ']'
    : 'NULL';
};
const sqlJsonb = (val) => {
  let json = '{}';
  try {
    json = JSON.stringify(val && typeof val === 'object' ? val : {});
  } catch (e) {
    console.warn('Prep Mention Insert: raw_data was not JSON-serializable, storing empty object');
  }
  return "'" + sqlString(json) + "'::jsonb";
};

for (const item of items) {
  const d = item.json;

  const platformRaw = String(d.platform || 'other').trim().toLowerCase();
  const platform = validPlatforms.includes(platformRaw) ? platformRaw : 'other';
  const externalId = cleanString(d.external_id || 'unknown').slice(0, 255) || 'unknown';
  const language = cleanString(d.language || 'en').slice(0, 10) || 'en';

  const createdAtDate = new Date(d.created_at || Date.now());
  const safeCreatedAt = Number.isNaN(createdAtDate.getTime()) ? new Date() : createdAtDate;

  const query = [
    'INSERT INTO social_mentions (',
    '  platform, external_id, text_content, language, created_at,',
    '  author_username, author_id, author_verified, author_followers_count, author_description,',
    '  likes_count, shares_count, replies_count, views_count,',
    '  urls, hashtags, mentions,',
    '  has_media, is_reply, is_quote, reply_to_id, conversation_id,',
    '  raw_data, processing_status',
    ') VALUES (',
    '  ' + sqlText(platform) + ',',
    '  ' + sqlText(externalId) + ',',
    '  ' + sqlText(d.text_content || '') + ',',
    '  ' + sqlText(language) + ',',
    '  ' + sqlTimestamp(d.created_at) + ',',
    '  ' + sqlText(d.author_username || 'unknown', 'unknown', 255) + ',',
    '  ' + sqlText(d.author_id || 'unknown', 'unknown', 255) + ',',
    '  ' + sqlBool(d.author_verified) + ',',
    '  ' + sqlNonNegativeInt(d.author_followers_count) + ',',
    '  ' + sqlText(d.author_description, null) + ',',
    '  ' + sqlNonNegativeInt(d.likes_count) + ',',
    '  ' + sqlNonNegativeInt(d.shares_count) + ',',
    '  ' + sqlNonNegativeInt(d.replies_count) + ',',
    '  ' + sqlNonNegativeInt(d.views_count) + ',',
    '  ' + sqlTextArray(d.urls) + ',',
    '  ' + sqlTextArray(d.hashtags, 100) + ',',
    '  ' + sqlTextArray(d.mentions, 100) + ',',
    '  ' + sqlBool(d.has_media) + ',',
    '  ' + sqlBool(d.is_reply) + ',',
    '  ' + sqlBool(d.is_quote) + ',',
    '  ' + sqlText(d.reply_to_id, null, 255) + ',',
    '  ' + sqlText(d.conversation_id, null, 255) + ',',
    '  ' + sqlJsonb(d.raw_data) + ',',
    "  'processed'",
    ')',
    'ON CONFLICT (platform, external_id) DO UPDATE SET',
    '  likes_count = EXCLUDED.likes_count,',
    '  shares_count = EXCLUDED.shares_count,',
    '  replies_count = EXCLUDED.replies_count,',
    '  views_count = EXCLUDED.views_count,',
    "  processing_status = 'processed',",
    '  last_updated = NOW()',
    'RETURNING mention_id;'
  ].join(String.fromCharCode(10));

  result.push({
    json: {
      query,

      // Carry forward sanitized helpers for observability/backwards compatibility
      p_platform: platform,
      p_external_id: externalId,
      p_text_content: d.text_content || '',
      p_language: language,
      p_created_at: safeCreatedAt.toISOString(),
      p_author_username: d.author_username || 'unknown',
      p_author_id: d.author_id || 'unknown',
      p_author_verified: d.author_verified === true,
      p_author_followers_count: Number(sqlNonNegativeInt(d.author_followers_count)),
      p_author_description: d.author_description || null,
      p_likes_count: Number(sqlNonNegativeInt(d.likes_count)),
      p_shares_count: Number(sqlNonNegativeInt(d.shares_count)),
      p_replies_count: Number(sqlNonNegativeInt(d.replies_count)),
      p_views_count: Number(sqlNonNegativeInt(d.views_count)),
      p_urls_literal: sqlTextArray(d.urls),
      p_hashtags_literal: sqlTextArray(d.hashtags, 100),
      p_mentions_literal: sqlTextArray(d.mentions, 100),
      p_has_media: d.has_media === true,
      p_is_reply: d.is_reply === true,
      p_is_quote: d.is_quote === true,
      p_reply_to_id: d.reply_to_id || null,
      p_conversation_id: d.conversation_id || null,
      p_raw_data: d.raw_data || {},

      // Carry forward full original data for downstream nodes
      _original: d
    }
  });
}

return result;

// =============================================
// Enrich Mention + Prep Sentiment
// 1. Recovers original data lost by Postgres INSERT
// 2. Merges mention_id from INSERT result
// 3. Flattens sentiment fields for next INSERT
// Index correlation is safe: Prep→Postgres→Enrich is 1:1.
// =============================================

const items = $input.all();
const prepItems = $('Prep Mention Insert').all();
if (items.length !== prepItems.length) {
  console.warn('Enrich Mention: count mismatch — input=' + items.length + ' vs prep=' + prepItems.length);
}
const result = [];

for (let i = 0; i < items.length; i++) {
  // Detect INSERT error (continueOnFail returns {error:...} without mention_id)
  if (items[i].json.error || !items[i].json.mention_id) {
    console.warn('Enrich Mention: INSERT failed for item ' + i + ' (external_id=' + ((prepItems[i] && prepItems[i].json._original && prepItems[i].json._original.external_id) || 'unknown') + '): ' + (items[i].json.errorMessage || items[i].json.error || 'missing mention_id'));
    continue;
  }
  const prepOriginal = (prepItems[i] && prepItems[i].json._original) || {};
  // Step 1+2: Recover original data + add mention_id
  const d = {
    ...prepOriginal,
    mention_id: items[i].json.mention_id
  };

  // Step 3: Flatten sentiment fields for Postgres INSERT
  const s = d.sentiment || {};
  const vader = s.vader || {};
  const textblob = s.textblob || {};

  const clamp = (val, min, max) => Math.max(min, Math.min(max, Number(val) || 0));

  const validLabels = ['positive', 'neutral', 'negative', 'mixed'];
  const rawLabel = (s.sentiment_label || 'neutral').toLowerCase();
  const sentimentLabel = validLabels.includes(rawLabel) ? rawLabel : 'neutral';

  result.push({
    json: {
      p_mention_id: d.mention_id,
      p_vader_compound: clamp(vader.compound, -1, 1),
      p_vader_pos: clamp(vader.pos, 0, 1),
      p_vader_neu: clamp(vader.neu, 0, 1),
      p_vader_neg: clamp(vader.neg, 0, 1),
      p_textblob_polarity: clamp(textblob.polarity, -1, 1),
      p_textblob_subjectivity: clamp(textblob.subjectivity, 0, 1),
      p_final_sentiment_score: clamp(s.ensemble_score, -1, 1),
      p_sentiment_label: sentimentLabel,
      p_confidence_score: clamp(s.confidence_score || 0.5, 0, 1),

      _original: d
    }
  });
}

return result;

// =============================================
// Enrich Sentiment + Prep Threat
// 1. Recovers original data lost by Postgres INSERT
// 2. Merges sentiment_id from INSERT result
// 3. Flattens threat fields for next INSERT
// Index correlation is safe: Prep→Postgres→Enrich is 1:1.
// =============================================

const items = $input.all();
const prepItems = $('Enrich Mention + Prep Sentiment').all();
if (items.length !== prepItems.length) {
  console.warn('Enrich Sentiment: count mismatch — input=' + items.length + ' vs prep=' + prepItems.length);
}
const result = [];

for (let i = 0; i < items.length; i++) {
  // Detect INSERT error (continueOnFail returns {error:...} without sentiment_id)
  if (items[i].json.error || !items[i].json.sentiment_id) {
    console.warn('Enrich Sentiment: INSERT failed for item ' + i + ' (mention_id=' + ((prepItems[i] && prepItems[i].json._original && prepItems[i].json._original.mention_id) || 'unknown') + '): ' + (items[i].json.errorMessage || items[i].json.error || 'missing sentiment_id'));
    continue;
  }
  const prepOriginal = (prepItems[i] && prepItems[i].json._original) || {};
  // Step 1+2: Recover original data + add sentiment_id
  const d = {
    ...prepOriginal,
    sentiment_id: items[i].json.sentiment_id
  };

  // Step 3: Flatten threat fields for Postgres INSERT
  const t = d.threat || {};

  const esc = (val) => val == null ? '' : String(val).replace(/\0/g, '').replace(/'/g, "''");
  const clamp = (val, min, max) => Math.max(min, Math.min(max, Number(val) || 0));

  const validLevels = ['low', 'medium', 'high', 'critical'];
  const critLevel = validLevels.includes(t.criticality_level) ? t.criticality_level : 'low';

  const keywords = t.matched_keywords || [];
  const keywordsLiteral = keywords.length > 0
    ? 'ARRAY[' + keywords.map(k => "'" + esc(k) + "'").join(',') + ']'
    : 'NULL';

  const riskScore = Math.min(100, Math.max(0, Math.round(t.raw_score || 0)));

  result.push({
    json: {
      p_mention_id: d.mention_id,
      p_sentiment_id: d.sentiment_id,
      p_threat_type: esc(t.threat_type || 'general'),
      p_threat_category: esc(t.threat_category || 'other'),
      p_criticality_level: critLevel,
      p_confidence_score: clamp(t.confidence_score || 0, 0, 1),
      p_matched_keywords_literal: keywordsLiteral,
      p_risk_score: riskScore,

      _original: d
    }
  });
}

return result;

// =============================================
// Enrich After Threat
// Merges detection_id back with full data.
// Reads _original from the previous Prep node
// via index (1:1 Prep→Postgres→Enrich by design).
// Flattens criticality_level for the IF node.
// =============================================

const items = $input.all();
const prepItems = $('Enrich Sentiment + Prep Threat').all();
if (items.length !== prepItems.length) {
  console.warn('Enrich After Threat: count mismatch — input=' + items.length + ' vs prep=' + prepItems.length);
}

const result = [];
for (let i = 0; i < items.length; i++) {
  // Detect INSERT error (continueOnFail returns {error:...} without detection_id)
  if (items[i].json.error || !items[i].json.detection_id) {
    console.warn('Enrich After Threat: INSERT failed for item ' + i + ' (mention_id=' + ((prepItems[i] && prepItems[i].json._original && prepItems[i].json._original.mention_id) || 'unknown') + '): ' + (items[i].json.errorMessage || items[i].json.error || 'missing detection_id'));
    continue;
  }
  const original = (prepItems[i] && prepItems[i].json._original) || {};
  result.push({
    json: {
      ...original,
      detection_id: items[i].json.detection_id,
      criticality_level: (original.threat || {}).criticality_level || 'low'
    }
  });
}
return result;

