      ]
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: '*Keywords:*\n' + (matchedKeywords || 'ninguno') }
    },
    {
      type: 'actions',
      elements: [
        { type: 'button', text: { type: 'plain_text', text: 'Ver Original' }, url: sourceUrl, style: 'primary' },
        { type: 'button', text: { type: 'plain_text', text: 'Falso Positivo' }, value: 'fp_' + data.detection_id, action_id: 'mark_false_positive' }
      ]
    },
    {
      type: 'context',
      elements: [
        { type: 'mrkdwn', text: 'Detection ID: ' + data.detection_id + ' | Mention ID: ' + data.mention_id }
