  // Email HTML
  const emailHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>' +
    'body{font-family:Arial,sans-serif;line-height:1.6;color:#333}' +
    '.container{max-width:600px;margin:0 auto;padding:20px}' +
    '.header{background:' + color + ';color:white;padding:20px;text-align:center;border-radius:5px 5px 0 0}' +
    '.content{background:#f9fafb;padding:20px;border:1px solid #e5e7eb}' +
    '.section{margin-bottom:20px}.label{font-weight:bold;color:#4b5563}' +
    '.value{margin-top:5px}' +
    '.button{display:inline-block;padding:12px 24px;background:' + color + ';color:white;text-decoration:none;border-radius:5px;margin:10px 5px}' +
    '.footer{background:#f3f4f6;padding:15px;text-align:center;font-size:12px;color:#6b7280}' +
    '</style></head><body><div class="container">' +
    '<div class="header"><h1>' + emoji + ' ALERTA DE AMENAZA</h1><p>Criticidad: ' + critLevel.toUpperCase() + '</p></div>' +
    '<div class="content">' +
    '<div class="section"><div class="label">Contenido</div><div class="value" style="background:white;padding:15px;border-left:4px solid ' + color + '">' + safeTextContent + '</div></div>' +
    '<div class="section"><div class="label">Autor</div><div class="value">' + safeAuthor + '</div></div>' +
    '<div style="text-align:center;margin-top:30px"><a href="' + safeSourceUrl + '" class="button">Ver Original</a></div>' +
    '</div>' +
    '<div class="footer"><p>Detection ID: ' + safeDetectionId + ' | ' + safeTimestamp + '</p></div>' +
    '</div></body></html>';

  const alertMessage = emoji + ' *ALERTA ' + critLevel.toUpperCase() + '*: ' + textContent.substring(0, 100) + '...';

  alerts.push({
    json: {
      ...data,
      // CRITICAL: alert_severity uses the MAPPED value, not criticality_level directly
      alert_severity: alertSeverity,
      alert_message: alertMessage,
      slack_blocks: slackBlocks,
      email_subject: '[' + critLevel.toUpperCase() + '] Amenaza detectada',
      email_html: emailHtml
